H.background();
const r = P.r;
const m1 = 1.0, m2 = m1 * r;
const u1 = 3.0, u2 = -2.0;
const ptot = m1 * u1 + m2 * u2;
const vcm = ptot / (m1 + m2);
H.text("Conservation of Momentum:  m1*u1 + m2*u2 = m1*v1 + m2*v2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("No external force => total momentum p is the same before and after the collision", 24, 52, { color: H.colors.sub, size: 13 });
const cx = 450, trackY = 250, halfW = 380;
H.line(cx - halfW, trackY + 28, cx + halfW, trackY + 28, { color: H.colors.grid, width: 2 });
const period = 6;
const ph = (t % period) / period;
const collide = 0.5;
let x1, x2, sv1, sv2;
if (ph < collide) {
  const f = ph / collide;
  x1 = cx - 240 + u1 * 26 * f;
  x2 = cx + 240 + u2 * 26 * f;
  sv1 = u1; sv2 = u2;
} else {
  const f = (ph - collide) / (1 - collide);
  const v1 = (m1 - m2) / (m1 + m2) * u1 + (2 * m2) / (m1 + m2) * u2;
  const v2 = (2 * m1) / (m1 + m2) * u1 + (m2 - m1) / (m1 + m2) * u2;
  const cx1 = cx - 240 + u1 * 26 * collide;
  const cx2 = cx + 240 + u2 * 26 * collide;
  x1 = cx1 + v1 * 26 * f;
  x2 = cx2 + v2 * 26 * f;
  sv1 = v1; sv2 = v2;
}
const w1 = 36 + 10 * m1, w2 = 36 + 10 * m2;
H.rect(x1 - w1 / 2, trackY - 4, w1, 32, { fill: H.colors.accent, stroke: H.colors.ink, width: 2, radius: 4 });
H.rect(x2 - w2 / 2, trackY - 4, w2, 32, { fill: H.colors.violet, stroke: H.colors.ink, width: 2, radius: 4 });
H.arrow(x1, trackY + 12, x1 + sv1 * 14, trackY + 12, { color: H.colors.warn, width: 3 });
H.arrow(x2, trackY + 12, x2 + sv2 * 14, trackY + 12, { color: H.colors.warn, width: 3 });
H.text("m1 = " + m1.toFixed(1) + " kg", x1 - w1 / 2, trackY - 14, { color: H.colors.accent, size: 12 });
H.text("m2 = " + m2.toFixed(1) + " kg", x2 - w2 / 2, trackY - 14, { color: H.colors.violet, size: 12 });
const phase = ph < collide ? "BEFORE" : "AFTER";
H.text("Phase: " + phase, 24, 360, { color: H.colors.good, size: 14, weight: 700 });
H.text("u1 = +" + u1.toFixed(1) + " m/s,  u2 = " + u2.toFixed(1) + " m/s", 24, 384, { color: H.colors.sub, size: 13 });
H.text("p_total = m1*u1 + m2*u2 = " + ptot.toFixed(2) + " kg*m/s  (conserved)", 24, 408, { color: H.colors.accent, size: 14, weight: 700 });
H.text("v_cm = p/(m1+m2) = " + vcm.toFixed(2) + " m/s", 24, 432, { color: H.colors.violet, size: 13 });
